WITH passing AS (
  SELECT * FROM students WHERE score >= 60
)
SELECT name, score FROM passing ORDER BY score DESC;

CREATE TABLE IF NOT EXISTS notes (
  id INTEGER PRIMARY KEY,
  body VARCHAR(255) NOT NULL
);

SELECT name, score,
  DENSE_RANK() OVER (ORDER BY score DESC) AS position
FROM students;

SELECT c.title, COUNT(s.id) AS students, ROUND(AVG(s.score), 1) AS average_score
FROM courses AS c LEFT JOIN students AS s ON c.id = s.course_id
GROUP BY c.id, c.title ORDER BY average_score DESC;
